206	/**
207	 * @brief Select SDMMC clock source
208	 *
209	 * @param hw       hardware instance address
210	 * @param clk_src  clock source, see valid sources in type `soc_periph_sdmmc_clk_src_t`
211	 */
212	static inline void sdmmc_ll_select_clk_source(sdmmc_dev_t *hw, soc_periph_sdmmc_clk_src_t clk_src)
213	{
214	    uint32_t clk_val = 0;
215	    switch (clk_src) {
216	    case SDMMC_CLK_SRC_PLL160M:
217	        clk_val = 0;
218	        break;
219	    case SDMMC_CLK_SRC_SDIO_200M:
220	        clk_val = 1;
221	        break;
222	    default:
223	        HAL_ASSERT(false);
224	        break;
225	    }
226	
227	    HP_SYS_CLKRST.peri_clk_ctrl01.reg_sdio_ls_clk_src_sel = clk_val;
228	    HP_SYS_CLKRST.peri_clk_ctrl01.reg_sdio_ls_clk_en = true;
229	}
