238	/**
239	 * @brief Set SDMMC clock div
240	 *
241	 * @param hw     hardware instance address
242	 * @param div    divider value
243	 */
244	static inline void sdmmc_ll_set_clock_div(sdmmc_dev_t *hw, uint32_t div)
245	{
246	    if (div > 1) {
247	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_h = div / 2 - 1;
248	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_n = div - 1;
249	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_l = div - 1;
250	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_cfg_update = 1;
251	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_cfg_update = 0;
252	    } else {
253	        HP_SYS_CLKRST.peri_clk_ctrl01.reg_sdio_hs_mode = 1;
254	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_h = 0;
255	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_n = 0;
256	        HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_l = 0;
257	    }
258	}
