277	/**
278	 * @brief Get SDMMC clock div
279	 *
280	 * @param hw    hardware instance address
281	 *
282	 * @return      Divider value
283	 */
284	static inline uint32_t sdmmc_ll_get_clock_div(sdmmc_dev_t *hw)
285	{
286	    uint32_t div = 0;
287	    if (HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_h == 0 &&
288	            HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_n == 0 &&
289	            HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_l == 0) {
290	        div = 1;
291	    } else {
292	        div = HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_clk_edge_l + 1;
293	    }
294	
295	    return div;
296	}
