324	/**
325	 * @brief Set SDMMC din delay phase
326	 *
327	 * @param hw     hardware instance address
328	 * @param phase  delay phase
329	 * @param mode   speed mode
330	 */
331	static inline void sdmmc_ll_set_din_delay_phase(sdmmc_dev_t *hw, sdmmc_ll_delay_phase_t phase, sdmmc_ll_speed_mode_t mode)
332	{
333	    if (mode == SDMMC_LL_SPEED_MODE_LS) {
334	        switch (phase) {
335	        case SDMMC_LL_DELAY_PHASE_1:
336	            HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_sam_clk_edge_sel = 0x1;
337	            break;
338	        case SDMMC_LL_DELAY_PHASE_2:
339	            HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_sam_clk_edge_sel = 0x2;
340	            break;
341	        case SDMMC_LL_DELAY_PHASE_3:
342	            HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_sam_clk_edge_sel = 0x3;
343	            break;
344	        default:
345	            HP_SYS_CLKRST.peri_clk_ctrl02.reg_sdio_ls_sam_clk_edge_sel = 0x0;
346	            break;
347	        }
348	    } else {
349	        SDMMC.dll_clk_conf.dll_cclk_in_sam_phase = (phase << 3);
350	    }
351	}
