374	/**
375	 * @brief Set SDMMC din delay line
376	 *
377	 * @param hw     hardware instance address
378	 * @param phase  delay line
379	 * @param mode   speed mode
380	 */
381	static inline void sdmmc_ll_set_din_delay_line(sdmmc_dev_t *hw, sdmmc_ll_delay_line_t phase, sdmmc_ll_speed_mode_t mode)
382	{
383	    SDMMC.dll_clk_conf.dll_cclk_in_sam_phase &= ~0x7;
384	    if (mode == SDMMC_LL_SPEED_MODE_HS) {
385	        SDMMC.dll_clk_conf.dll_cclk_in_sam_phase |= phase;
386	    } else {
387	        HAL_ASSERT(false);
388	    }
389	}
