74	esp_err_t sd_host_create_sdmmc_controller(const sd_host_sdmmc_cfg_t *config, sd_host_ctlr_handle_t *ret_handle)
75	{
76	    esp_err_t ret = ESP_FAIL;
77	    ESP_RETURN_ON_FALSE(config && ret_handle, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
78	
79	    sd_host_sdmmc_ctlr_t *ctlr = heap_caps_calloc(1, sizeof(sd_host_sdmmc_ctlr_t), SD_HOST_SDMMC_MEM_ALLOC_CAPS);
80	    ESP_RETURN_ON_FALSE(ctlr, ESP_ERR_NO_MEM, TAG, "no mem for sd host controller context");
81	
82	    ret = sd_host_claim_controller(ctlr);
83	    if (ret != ESP_OK) {
84	        //claim fail, clean and return directly
85	        free(ctlr);
86	        ESP_RETURN_ON_ERROR(ret, TAG, "no available sd host controller");
87	    }
88	
89	    ctlr->dma_desc_num = config->dma_desc_num ? config->dma_desc_num : SD_HOST_SDMMC_DMA_DESC_CNT;
90	    ctlr->dma_desc = heap_caps_calloc(1, sizeof(sdmmc_desc_t) * ctlr->dma_desc_num, SD_HOST_SDMMC_DMA_ALLOC_CAPS);
91	    ESP_LOGD(TAG, "ctlr->dma_desc addr: %p", ctlr->dma_desc);
92	    ESP_RETURN_ON_FALSE(ctlr->dma_desc, ESP_ERR_NO_MEM, TAG, "no mem for dma descriptors");
93	
94	    ctlr->io_intr_sem = xSemaphoreCreateBinaryWithCaps(SD_HOST_SDMMC_MEM_ALLOC_CAPS);
95	    ESP_GOTO_ON_FALSE(ctlr->io_intr_sem, ESP_ERR_NO_MEM, err, TAG, "no mem for io interrupt semaphore");
96	
97	    ctlr->mutex = xSemaphoreCreateMutexWithCaps(SD_HOST_SDMMC_MEM_ALLOC_CAPS);
98	    ESP_GOTO_ON_FALSE(ctlr->mutex, ESP_ERR_NO_MEM, err, TAG, "no mem for mutex");
99	
100	    ctlr->event_queue = xQueueCreateWithCaps(config->event_queue_items ? config->event_queue_items : 4, sizeof(sd_host_sdmmc_event_t), SD_HOST_SDMMC_MEM_ALLOC_CAPS);
101	    ESP_GOTO_ON_FALSE(ctlr->event_queue, ESP_ERR_NO_MEM, err, TAG, "no mem for mutex");
102	
103	    //use `ETS_SDIO_HOST_INTR_SOURCE` for now, replace with `sdmmc_periph.c` then. IDF-12585
104	    ESP_GOTO_ON_ERROR(esp_intr_alloc(ETS_SDIO_HOST_INTR_SOURCE, 0, &sd_host_isr, ctlr, &ctlr->intr_handle), err, TAG, "failed to install interrupt service");
105	
106	#if CONFIG_PM_ENABLE
107	    ESP_GOTO_ON_ERROR(esp_pm_lock_create(ESP_PM_APB_FREQ_MAX, 0, "sdmmc", &ctlr->pm_lock), err, TAG, "failed to create pm lock");
108	#endif //CONFIG_PM_ENABLE
109	
110	    sdmmc_hal_init(&ctlr->hal);
111	    PERIPH_RCC_ATOMIC() {
112	        sdmmc_ll_pad_set_pin_dedicated_ctrl(ctlr->hal.dev, true);
113	    }
114	    ESP_GOTO_ON_ERROR(esp_clk_tree_enable_src(SDMMC_CLK_SRC_DEFAULT, true), err, TAG, "failed to acquire clk");
115	    uint32_t src_freq_hz = 0;
116	    esp_clk_tree_src_get_freq_hz(SDMMC_CLK_SRC_DEFAULT, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &src_freq_hz);
117	    ESP_EARLY_LOGI(TAG, "src_freq_hz: %d", src_freq_hz);
118	    sd_host_set_clk_div(ctlr, SDMMC_CLK_SRC_DEFAULT, SDMMC_LL_DEFAULT_DIV);
119	
120	    // Reset
121	    esp_err_t err = sd_host_reset(ctlr);
122	    if (err != ESP_OK) {
123	        ESP_LOGE(TAG, "%s: sd_host_reset returned 0x%x", __func__, err);
124	        return err;
125	    }
126	
127	    ESP_LOGD(TAG, "peripheral version %"PRIx32", hardware config %08"PRIx32, sdmmc_ll_get_version_id(ctlr->hal.dev), sdmmc_ll_get_hw_config_info(ctlr->hal.dev));
128	
129	    sdmmc_ll_clear_interrupt(ctlr->hal.dev, 0xffffffff);
130	    sdmmc_ll_enable_interrupt(ctlr->hal.dev, 0xffffffff, false);
131	    sdmmc_ll_enable_global_interrupt(ctlr->hal.dev, false);
132	    sdmmc_ll_init_dma(ctlr->hal.dev);
133	
134	    ctlr->spinlock = (portMUX_TYPE)portMUX_INITIALIZER_UNLOCKED;
135	    ctlr->drv.del_ctlr = sd_host_del_sdmmc_controller;
136	    *ret_handle = &ctlr->drv;
137	
138	    return ESP_OK;
139	
140	err:
141	    sd_host_del_sdmmc_controller(&ctlr->drv);
142	
143	    return ret;
144	}
