588	esp_err_t sd_host_slot_set_card_clk(sd_host_sdmmc_slot_t *slot)
589	{
590	    // Disable clock first
591	    sdmmc_ll_enable_card_clock(slot->ctlr->hal.dev, slot->slot_id, false);
592	    esp_err_t ret = sd_host_slot_clock_update_command(slot, false);
593	    ESP_RETURN_ON_ERROR(ret, TAG, "%s: sd_host_slot_clock_update_command returned 0x%x, failed to disable clk, ", __func__, ret);
594	
595	    int freq_khz = 0;
596	    if (slot->freq.freq_state == SD_HOST_SLOT_STATE_READY) {
597	        freq_khz = slot->freq.freq_hz / 1000;
598	    } else {
599	        freq_khz = 400;
600	    }
601	    ESP_LOGD(TAG, "freq: %d khz, state: %d", freq_khz, slot->freq.freq_state);
602	
603	    soc_periph_sdmmc_clk_src_t clk_src = 0;
604	    int host_div = 0;   /* clock divider of the host (SDMMC.clock) */
605	    int card_div = 0;   /* 1/2 of card clock divider (SDMMC.clkdiv) */
606	    sd_host_slot_get_clk_dividers(slot, freq_khz, &host_div, &card_div, &clk_src);
607	
608	    int real_freq_khz = sd_host_calc_freq(clk_src, host_div, card_div);
609	    slot->freq.real_freq_hz = real_freq_khz * 1000;
610	    ESP_LOGD(TAG, "slot_id=%d clk_src=%d host_div=%d card_div=%d freq=%dkHz (max %" PRIu32 "kHz)", slot->slot_id, clk_src, host_div, card_div, real_freq_khz, freq_khz);
611	
612	    // Program card clock settings, send them to the CIU
613	    sdmmc_ll_set_card_clock_div(slot->ctlr->hal.dev, slot->slot_id, card_div);
614	    sd_host_set_clk_div(slot->ctlr, clk_src, host_div);
615	    ret = sd_host_slot_clock_update_command(slot, false);
616	    if (ret != ESP_OK) {
617	        ESP_LOGE(TAG, "setting clk div failed");
618	        ESP_LOGE(TAG, "%s: sd_host_slot_clock_update_command returned 0x%x", __func__, ret);
619	        return ret;
620	    }
621	
622	    // Re-enable clocks
623	    sdmmc_ll_enable_card_clock(slot->ctlr->hal.dev, slot->slot_id, true);
624	    sdmmc_ll_enable_card_clock_low_power(slot->ctlr->hal.dev, slot->slot_id, true);
625	    ret = sd_host_slot_clock_update_command(slot, false);
626	    if (ret != ESP_OK) {
627	        ESP_LOGE(TAG, "re-enabling clk failed");
628	        ESP_LOGE(TAG, "%s: sd_host_slot_clock_update_command returned 0x%x", __func__, ret);
629	        return ret;
630	    }
631	
632	    const uint32_t data_timeout_ms = 100;
633	    uint32_t data_timeout_cycles = data_timeout_ms * freq_khz;
634	    sdmmc_ll_set_data_timeout(slot->ctlr->hal.dev, data_timeout_cycles);
635	    // always set response timeout to highest value, it's small enough anyway
636	    sdmmc_ll_set_response_timeout(slot->ctlr->hal.dev, 255);
637	
638	    return ESP_OK;
639	}
