713	esp_err_t sd_host_set_delay_phase(sd_host_sdmmc_slot_t *slot)
714	{
715	#if SDMMC_LL_DELAY_PHASE_SUPPORTED
716	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
717	
718	    sdmmc_delay_phase_t delay_phase = SDMMC_DELAY_PHASE_0;
719	    if (slot->delay_phase.delay_phase_state == SD_HOST_SLOT_STATE_READY) {
720	        delay_phase = slot->delay_phase.delayphase;
721	    }
722	
723	    uint32_t clk_src_freq_hz = 0;
724	    ESP_RETURN_ON_ERROR(esp_clk_tree_src_get_freq_hz(slot->clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clk_src_freq_hz),
725	                        TAG, "get source clock frequency failed");
726	
727	    //Now we're in high speed. Note ESP SDMMC Host HW only supports integer divider.
728	    int delay_phase_num = 0;
729	    sdmmc_ll_delay_phase_t phase = SDMMC_LL_DELAY_PHASE_0;
730	    sdmmc_ll_speed_mode_t speed_mode = (slot->freq.freq_hz / 1000) == SDMMC_FREQ_SDR104 ? SDMMC_LL_SPEED_MODE_HS : SDMMC_LL_SPEED_MODE_LS;
731	    switch (delay_phase) {
732	    case SDMMC_DELAY_PHASE_1:
733	        phase = SDMMC_LL_DELAY_PHASE_1;
734	        delay_phase_num = 1;
735	        break;
736	    case SDMMC_DELAY_PHASE_2:
737	        phase = SDMMC_LL_DELAY_PHASE_2;
738	        delay_phase_num = 2;
739	        break;
740	    case SDMMC_DELAY_PHASE_3:
741	        phase = SDMMC_LL_DELAY_PHASE_3;
742	        delay_phase_num = 3;
743	        break;
744	#if SOC_SDMMC_DELAY_PHASE_NUM > 4
745	    case SDMMC_DELAY_PHASE_4:
746	        phase = SDMMC_LL_DELAY_PHASE_4;
747	        delay_phase_num = 4;
748	        break;
749	    case SDMMC_DELAY_PHASE_5:
750	        phase = SDMMC_LL_DELAY_PHASE_5;
751	        delay_phase_num = 5;
752	        break;
753	    case SDMMC_DELAY_PHASE_6:
754	        phase = SDMMC_LL_DELAY_PHASE_6;
755	        delay_phase_num = 6;
756	        break;
757	    case SDMMC_DELAY_PHASE_7:
758	        phase = SDMMC_LL_DELAY_PHASE_7;
759	        delay_phase_num = 7;
760	        break;
761	#endif
762	    default:
763	        phase = SDMMC_LL_DELAY_PHASE_0;
764	        delay_phase_num = 0;
765	        break;
766	    }
767	    PERIPH_RCC_ATOMIC() {
768	        sdmmc_ll_set_din_delay_phase(slot->ctlr->hal.dev, phase, speed_mode);
769	        sdmmc_ll_set_dout_delay_phase(slot->ctlr->hal.dev, phase, speed_mode);
770	    }
771	
772	    int src_clk_period_ps = (1 * 1000 * 1000) / (clk_src_freq_hz / (1 * 1000 * 1000));
773	    int delay_phase_total_num = (slot->freq.freq_hz / 1000) == SDMMC_FREQ_SDR104 ? SOC_SDMMC_DELAY_PHASE_NUM : SDMMC_LL_DELAY_MAX_NUMS_LS;
774	    ESP_LOGD(TAG, "slot->freq.freq_hz: %d, delay_phase_total_num: %d", slot->freq.freq_hz, delay_phase_total_num);
775	    int phase_diff_ps = src_clk_period_ps * sdmmc_ll_get_clock_div(slot->ctlr->hal.dev) / delay_phase_total_num;
776	    ESP_LOGD(TAG, "difference between delay phases is %d ps", phase_diff_ps);
777	    ESP_LOGD(TAG, "host sampling edge is delayed by %d ps", phase_diff_ps * delay_phase_num);
778	
779	    return ESP_OK;
780	#else
781	    //DIG-217
782	    ESP_LOGD(TAG, "esp32 doesn't support phase delay, fallback to 0 delay");
783	    return ESP_OK;
784	#endif
785	}
