886	/*---------------------------------------------------------------
887	                    Static: ISR Handler
888	---------------------------------------------------------------*/
889	static void sd_host_isr(void *arg)
890	{
891	    sd_host_sdmmc_ctlr_t *ctlr = (sd_host_sdmmc_ctlr_t *)arg;
892	    sd_host_sdmmc_slot_t *slot = ctlr->slot[ctlr->cur_slot_id];
893	
894	    if (slot == NULL) {
895	        uint32_t pending = sdmmc_ll_get_intr_status(ctlr->hal.dev);
896	        uint32_t dma_pending = sdmmc_ll_get_idsts_interrupt_raw(ctlr->hal.dev);
897	        sdmmc_ll_clear_interrupt(ctlr->hal.dev, pending);
898	        sdmmc_ll_clear_idsts_interrupt(ctlr->hal.dev, dma_pending);
899	        return;
900	    }
901	
902	    sd_host_sdmmc_event_t event = {};
903	    bool need_yield = false;
904	    int higher_priority_task_awoken = pdFALSE;
905	
906	    uint32_t pending = sdmmc_ll_get_intr_status(ctlr->hal.dev) & SDMMC_LL_SD_EVENT_MASK;
907	    sdmmc_ll_clear_interrupt(ctlr->hal.dev, pending);
908	    event.sdmmc_status = pending;
909	
910	    uint32_t dma_pending = sdmmc_ll_get_idsts_interrupt_raw(ctlr->hal.dev);
911	    sdmmc_ll_clear_idsts_interrupt(ctlr->hal.dev, dma_pending);
912	
913	    if (dma_pending & SDMMC_LL_EVENT_DMA_NI) {
914	        // refill DMA descriptors
915	        size_t free_desc = sd_host_get_free_descriptors_count(slot);
916	        if (free_desc > 0) {
917	            sd_host_fill_dma_descriptors(slot, free_desc);
918	            sd_host_dma_resume(slot);
919	        }
920	        //NI, logic OR of TI and RI. This is a sticky bit and must be cleared each time TI or RI is cleared.
921	        dma_pending &= ~(SDMMC_LL_EVENT_DMA_NI | SDMMC_LL_EVENT_DMA_TI | SDMMC_LL_EVENT_DMA_RI);
922	    }
923	    event.dma_status = dma_pending & SDMMC_LL_EVENT_DMA_MASK;
924	
925	    if (pending != 0 || dma_pending != 0) {
926	        xQueueSendFromISR(ctlr->event_queue, &event, &higher_priority_task_awoken);
927	        if (slot->cbs.on_trans_done) {
928	            sd_host_evt_data_t edata = {};
929	            if (slot->cbs.on_trans_done(&slot->drv, &edata, slot->user_data)) {
930	                need_yield |= true;
931	            }
932	        }
933	    }
934	
935	    uint32_t sdio_pending = (sdmmc_ll_get_intr_status(ctlr->hal.dev) & (SDMMC_INTMASK_IO_SLOT1 | SDMMC_INTMASK_IO_SLOT0));
936	    if (sdio_pending) {
937	        // disable the interrupt (no need to clear here, this is done in sdmmc_host_io_int_wait)
938	        sdmmc_ll_enable_interrupt(ctlr->hal.dev, sdio_pending, false);
939	        xSemaphoreGiveFromISR(ctlr->io_intr_sem, &higher_priority_task_awoken);
940	        if (slot->cbs.on_io_interrupt) {
941	            sd_host_evt_data_t edata = {};
942	            if (slot->cbs.on_io_interrupt(&slot->drv, &edata, slot->user_data)) {
943	                need_yield |= true;
944	            }
945	        }
946	    }
947	
948	    need_yield |= higher_priority_task_awoken == pdTRUE;
949	    if (need_yield) {
950	        portYIELD_FROM_ISR();
951	    }
952	}
