954	/*---------------------------------------------------------------
955	                    HW Commands
956	---------------------------------------------------------------*/
957	esp_err_t sd_host_slot_start_command(sd_host_sdmmc_slot_t *slot, sdmmc_hw_cmd_t cmd, uint32_t arg)
958	{
959	    ESP_RETURN_ON_FALSE(slot, ESP_ERR_INVALID_ARG, TAG, "invalid argument: null pointer");
960	
961	    // if this isn't a clock update command, check the card detect status
962	    if (!sdmmc_ll_is_card_detected(slot->ctlr->hal.dev, slot->slot_id) && !cmd.update_clk_reg) {
963	        return ESP_ERR_NOT_FOUND;
964	    }
965	    if (cmd.data_expected && cmd.rw && sdmmc_ll_is_card_write_protected(slot->ctlr->hal.dev, slot->slot_id)) {
966	        return ESP_ERR_INVALID_STATE;
967	    }
968	    /* Outputs should be synchronized to cclk_out */
969	    cmd.use_hold_reg = 1;
970	
971	    int64_t yield_delay_us = 100 * 1000; // initially 100ms
972	    int64_t t0 = esp_timer_get_time();
973	    int64_t t1 = 0;
974	    bool skip_wait = (cmd.volt_switch && cmd.update_clk_reg);
975	    if (!skip_wait) {
976	        while (!(sdmmc_ll_is_command_taken(slot->ctlr->hal.dev))) {
977	            t1 = esp_timer_get_time();
978	            if (t1 - t0 > SD_HOST_SDMMC_START_CMD_TIMEOUT_US) {
979	                return ESP_ERR_TIMEOUT;
980	            }
981	            if (t1 - t0 > yield_delay_us) {
982	                yield_delay_us *= 2;
983	                vTaskDelay(1);
984	            }
985	        }
986	    }
987	    sdmmc_ll_set_command_arg(slot->ctlr->hal.dev, arg);
988	    cmd.card_num = slot->slot_id;
989	    cmd.start_command = 1;
990	    sdmmc_ll_set_command(slot->ctlr->hal.dev, cmd);
991	
992	    while (!(sdmmc_ll_is_command_taken(slot->ctlr->hal.dev))) {
993	        t1 = esp_timer_get_time();
994	        if (t1 - t0 > SD_HOST_SDMMC_START_CMD_TIMEOUT_US) {
995	            return ESP_ERR_TIMEOUT;
996	        }
997	        if (t1 - t0 > yield_delay_us) {
998	            yield_delay_us *= 2;
999	            vTaskDelay(1);
1000	        }
1001	    }
1002	    return ESP_OK;
1003	}
