1216	static void configure_pin_gpio_matrix(uint8_t gpio_num, uint8_t gpio_matrix_sig, gpio_mode_t mode, const char *name)
1217	{
1218	    assert(gpio_num != (uint8_t) GPIO_NUM_NC);
1219	    ESP_LOGD(TAG, "using GPIO%d as %s pin", gpio_num, name);
1220	    //todo: IDF-11125
1221	    gpio_reset_pin(gpio_num);
1222	    gpio_set_direction(gpio_num, mode);
1223	    gpio_pulldown_dis(gpio_num);
1224	    if (mode == GPIO_MODE_INPUT || mode == GPIO_MODE_INPUT_OUTPUT) {
1225	        esp_rom_gpio_connect_in_signal(gpio_num, gpio_matrix_sig, false);
1226	    }
1227	    if (mode == GPIO_MODE_OUTPUT || mode == GPIO_MODE_INPUT_OUTPUT) {
1228	        esp_rom_gpio_connect_out_signal(gpio_num, gpio_matrix_sig, false, false);
1229	    }
1230	}
