/****************************************************************************
 * Name: esp32p4_ciu_sendcmd
 *
 * Description:
 *   Function to send command to Card interface unit (CIU)
 *
 * Input Parameters:
 *   cmd - The command to be executed
 *   arg - The argument to use with the command.
 *
 * Returned Value:
 *   Returns zero on success.  One will be returned on a timeout.
 *
 ****************************************************************************/

static int esp32p4_ciu_sendcmd(uint32_t cmd, uint32_t arg)
{
  sdmmc_hw_cmd_t cmd_val;
  clock_t watchtime;

  watchtime = clock_systime_ticks();

  /* Wait for previous command to be taken by CIU */

  while (!sdmmc_ll_is_command_taken(&SDMMC))
    {
      if (clock_systime_ticks() - watchtime > SDCARD_CMDTIMEOUT)
        {
          mcerr("TMO Timed out waiting for command taken (%08" PRIx32 ")\n",
                SDMMC.cmd.val);
          return 1;
        }
    }

  /* Build the command register value from NuttX command encoding */

  memset(&cmd_val, 0, sizeof(cmd_val));

  /* Command index (bits 0-5) */

  cmd_val.cmd_index = (cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT;

  /* Response type (bits 6-9) */

  uint32_t resp = (cmd & MMCSD_RESPONSE_MASK) >> MMCSD_RESPONSE_SHIFT;

  switch (resp)
    {
      case MMCSD_NO_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        /* No response */
        break;

      case MMCSD_R1_RESPONSE >> MMCSD_RESPONSE_SHIFT:
      case MMCSD_R1B_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        cmd_val.check_response_crc = 1;
        break;

      case MMCSD_R2_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        cmd_val.response_long = 1;
        cmd_val.check_response_crc = 1;
        break;

      case MMCSD_R3_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        /* R3 has no CRC */
        break;

      case MMCSD_R4_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        break;

      case MMCSD_R5_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        cmd_val.check_response_crc = 1;
        break;

      case MMCSD_R6_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        cmd_val.check_response_crc = 1;
        break;

      case MMCSD_R7_RESPONSE >> MMCSD_RESPONSE_SHIFT:
        cmd_val.response_expect = 1;
        break;

      default:
        mcerr("ERROR: Unknown response type: %" PRIx32 "\n", resp);
        break;
    }

  /* Data transfer (bits 10-12) */

  uint32_t xfr = (cmd & MMCSD_DATAXFR_MASK) >> MMCSD_DATAXFR_SHIFT;

  if (xfr != 0)
    {
      cmd_val.data_expected = 1;

      if (cmd & MMCSD_WRXFR)
        {
          cmd_val.rw = 1;  /* Write */
        }

      if (cmd & MMCSD_STREAM)
        {
          cmd_val.transfer_mode = 1;  /* Stream mode */
        }
    }

  /* Send auto stop for multiblock transfers */

  if (cmd & MMCSD_MULTIBLOCK)
    {
      /* Don't send auto-stop; we'll send CMD12 manually */

      cmd_val.send_auto_stop = 0;
    }

  if (cmd & MMCSD_STOPXFR)
    {
      cmd_val.stop_abort_cmd = 1;
    }

  /* Wait for previous data transfer to complete */

  cmd_val.wait_complete = 1;

  /* Send initialization sequence (80 clocks) for CMD0 */

  if ((cmd & MMCSD_CMDIDX_MASK) == 0)
    {
      /* Don't send init sequence here, it's handled separately */

      cmd_val.send_init = 0;
    }

  /* Use hold register for synchronization */

  cmd_val.use_hold_reg = 1;

  /* Set card number */

  cmd_val.card_num = 0;

  /* Start command */

  cmd_val.start_command = 1;

  /* Set argument and send command */

  sdmmc_ll_set_command_arg(&SDMMC, arg);
  sdmmc_ll_set_command(&SDMMC, cmd_val);

  mcinfo("cmd=0x%" PRIx32 " arg=0x%" PRIx32 " cmd_val=0x%x\n",
         cmd, arg, cmd_val.val);

  return 0;
}

/****************************************************************************
 * Name: configure_pin
 *
 * Description:
 *   Configure a GPIO pin for SDMMC use via GPIO matrix.
 *
 * Input Parameters:
 *   gpio_pin - GPIO pin number
 *   sdio_pin - SDMMC signal number in GPIO matrix
 *   attr     - Pin attributes (INPUT, OUTPUT, etc.)
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void configure_pin(uint8_t gpio_pin, uint8_t sdio_pin,
                          gpio_pinattr_t attr)
{
  esp_gpio_config(gpio_pin, attr);

  if (attr & INPUT)
    {
      esp_rom_gpio_connect_in_signal(gpio_pin, sdio_pin, false);
    }

  if (attr & OUTPUT)
    {
      esp_rom_gpio_connect_out_signal(gpio_pin, sdio_pin, false, false);
    }
}

/****************************************************************************
 * Name: esp32p4_enable_ints
 *
 * Description:
 *   Enable/disable SD card interrupts per functional settings.
 *
 * Input Parameters:
 *   priv - A reference to the SD card device state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_enable_ints(struct esp32p4_dev_s *priv)
{
  uint32_t regval;

#ifdef CONFIG_ESP32P4_SDMMC_DMA
  mcinfo("waitmask=%04" PRIx32 " xfrmask=%04" PRIx32 " dmamask=%04" PRIx32
         " RINTSTS=%08" PRIx32 "\n",
         (uint32_t)priv->waitmask, (uint32_t)priv->xfrmask,
         (uint32_t)priv->dmamask,
         (uint32_t)sdmmc_ll_get_interrupt_raw(&SDMMC));
#else
  mcinfo("waitmask=%04" PRIx32 " xfrmask=%04" PRIx32 " RINTSTS=%08" PRIx32
         "\n",
         (uint32_t)priv->waitmask, (uint32_t)priv->xfrmask,
         (uint32_t)sdmmc_ll_get_interrupt_raw(&SDMMC));
#endif

  /* Enable SDMMC interrupts */

  regval = priv->xfrmask | priv->waitmask | SDCARD_INT_CDET;
  sdmmc_ll_enable_interrupt(&SDMMC, 0xffffffff, false);
  sdmmc_ll_enable_interrupt(&SDMMC, regval, true);
}

/****************************************************************************
 * Name: esp32p4_disable_allints
 *
 * Description:
 *   Disable all SD card interrupts.
 *
 * Input Parameters:
 *   priv - A reference to the SD card device state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_disable_allints(struct esp32p4_dev_s *priv)
{
#ifdef CONFIG_ESP32P4_SDMMC_DMA
  /* Disable DMA-related interrupts */

  priv->dmamask = 0;
#endif

  /* Disable all SDMMC interrupts (except card detect) */

  sdmmc_ll_enable_interrupt(&SDMMC, 0xffffffff, false);
  sdmmc_ll_enable_interrupt(&SDMMC, SDCARD_INT_CDET, true);
  priv->waitmask = 0;
  priv->xfrmask  = 0;
}

/****************************************************************************
 * Name: esp32p4_config_waitints
 *
 * Description:
 *   Enable/disable SD card interrupts needed to support the wait function
 *
 * Input Parameters:
 *   priv       - A reference to the SD card device state structure
 *   waitmask   - The set of bits in the SD card INTMASK register to set
 *   waitevents - Waited for events
 *   wkupevent  - Wake-up events
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_config_waitints(struct esp32p4_dev_s *priv,
                                    uint32_t waitmask,
                                    sdio_eventset_t waitevents,
                                    sdio_eventset_t wkupevent)
{
  irqstate_t flags;

  mcinfo("waitevents=%04x wkupevent=%04x\n",
         (unsigned)waitevents, (unsigned)wkupevent);

  /* Save all of the data and set the new interrupt mask in one, atomic
   * operation.
   */

  flags            = enter_critical_section();
  priv->waitevents = waitevents;
  priv->wkupevent  = wkupevent;
  priv->waitmask   = waitmask;

  esp32p4_enable_ints(priv);
  leave_critical_section(flags);
}

/****************************************************************************
 * Name: esp32p4_config_xfrints
 *
 * Description:
 *   Enable SD card interrupts needed to support the data transfer event
 *
 * Input Parameters:
 *   priv    - A reference to the SD card device state structure
 *   xfrmask - The set of bits in the SD card MASK register to set
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_config_xfrints(struct esp32p4_dev_s *priv,
                                   uint32_t xfrmask)
{
  irqstate_t flags;
  flags = enter_critical_section();

  priv->xfrmask = xfrmask;
  esp32p4_enable_ints(priv);

  leave_critical_section(flags);
}

/****************************************************************************
 * Name: esp32p4_eventtimeout
 *
 * Description:
 *   The watchdog timeout setup when the event wait start has expired without
 *   any other waited-for event occurring.
 *
 * Input Parameters:
 *   arg    - The argument
 *
 * Returned Value:
 *   None
 *
 * Assumptions:
 *   Always called from the interrupt level with interrupts disabled.
 *
 ****************************************************************************/

static void esp32p4_eventtimeout(wdparm_t arg)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)arg;

  /* There is always race conditions with timer expirations. */

  DEBUGASSERT((priv->waitevents & SDIOWAIT_TIMEOUT) != 0 ||
              priv->wkupevent != 0);

  /* Is a data transfer complete event expected? */

  if ((priv->waitevents & SDIOWAIT_TIMEOUT) != 0)
    {
      /* Yes.. wake up any waiting threads */

      esp32p4_endwait(priv, SDIOWAIT_TIMEOUT);
      mcerr("Timeout: remaining: %d\n", priv->remaining);
    }
}

/****************************************************************************
 * Name: esp32p4_endwait
 *
 * Description:
 *   Wake up a waiting thread if the waited-for event has occurred.
 *
 * Input Parameters:
 *   priv      - An instance of the SDIO device interface
 *   wkupevent - The event that caused the wait to end
 *
 * Returned Value:
 *   None
 *
 * Assumptions:
 *   Always called from the interrupt level with interrupts disabled.
 *
 ****************************************************************************/

static void esp32p4_endwait(struct esp32p4_dev_s *priv,
                            sdio_eventset_t wkupevent)
{
  mcinfo("wkupevent=%04x\n", (unsigned)wkupevent);

  /* Cancel the watchdog timeout */

  wd_cancel(&priv->waitwdog);

  /* Disable event-related interrupts */

  esp32p4_config_waitints(priv, 0, 0, wkupevent);

  /* Wake up the waiting thread */

  nxsem_post(&priv->waitsem);
}

/****************************************************************************
 * Name: esp32p4_endtransfer
 *
 * Description:
 *   Terminate a transfer with the provided status.  This function is called
 *   only from the SDIO interrupt handler when end-of-transfer conditions
 *   are detected.
 *
 * Input Parameters:
 *   priv   - An instance of the SDIO device interface
 *   wkupevent - The event that caused the transfer to end
 *
 * Returned Value:
 *   None
 *
 * Assumptions:
 *   Always called from the interrupt level with interrupts disabled.
 *
 ****************************************************************************/

static void esp32p4_endtransfer(struct esp32p4_dev_s *priv,
                                sdio_eventset_t wkupevent)
{
  mcinfo("wkupevent=%04x\n", (unsigned)wkupevent);

  /* Disable all transfer related interrupts */

  esp32p4_config_xfrints(priv, 0);

  /* Clearing pending interrupt status on all transfer related interrupts */

  sdmmc_ll_clear_interrupt(&SDMMC, priv->waitmask);

  /* Mark the transfer finished */

  priv->remaining = 0;

  /* Is a thread wait for these data transfer complete events? */

  if ((priv->waitevents & wkupevent) != 0)
    {
      /* Yes.. wake up any waiting threads */

      esp32p4_endwait(priv, wkupevent);
    }
}

/****************************************************************************
 * Name: esp32p4_interrupt
 *
 * Description:
 *   SDIO interrupt handler
 *
 * Input Parameters:
 *   dev - An instance of the SDIO device interface
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static int esp32p4_interrupt(int irq, void *context, void *arg)
{
  struct esp32p4_dev_s *priv = arg;
  uint32_t enabled;
  uint32_t pending;

  /* Loop while there are pending interrupts.  Check the SD card status
   * register.  Mask out all bits that don't correspond to enabled
   * interrupts.  (This depends on the fact that bits are ordered
   * the same in both the STA and MASK register).  If there are non-zero
   * bits remaining, then we have work to do here.
   */

  while ((enabled = sdmmc_ll_get_intr_status(&SDMMC)) != 0)
    {
      /* Clear pending status */

      sdmmc_ll_clear_interrupt(&SDMMC, enabled);

#ifdef CONFIG_MMCSD_HAVE_CARDDETECT
      /* Handle in card detection events ************************************/

      if ((enabled & SDMMC_LL_EVENT_CD) != 0)
        {
          sdio_statset_t cdstatus;

          /* Update card status */

          cdstatus = priv->cdstatus;
          if (!sdmmc_ll_is_card_detected(&SDMMC, priv->slot))
            {
              priv->cdstatus |= SDIO_STATUS_PRESENT;

#ifdef CONFIG_MMCSD_HAVE_WRITEPROTECT
              if (sdmmc_ll_is_card_write_protected(&SDMMC, priv->slot))
                {
                  priv->cdstatus |= SDIO_STATUS_WRPROTECTED;
                }
              else
#endif
                {
                  priv->cdstatus &= ~SDIO_STATUS_WRPROTECTED;
                }
            }
          else
            {
              priv->cdstatus &=
                ~(SDIO_STATUS_PRESENT | SDIO_STATUS_WRPROTECTED);
            }

          mcinfo("cdstatus OLD: %02x NEW: %02x\n", cdstatus, priv->cdstatus);

          /* Perform any requested callback if the status has changed */

          if (cdstatus != priv->cdstatus)
            {
              esp32p4_callback(priv);
            }
        }
#endif

      /* Handle data transfer events ****************************************/

      pending = enabled & priv->xfrmask;
      if (pending != 0)
        {
          /* Handle data request events */

          if ((pending & SDMMC_LL_EVENT_TXDR) != 0)
            {
              uint32_t status;

              /* Transfer data to the TX FIFO */

              DEBUGASSERT(priv->wrdir);

              for (status = SDMMC.status.val;
                   (status & SDMMC_STATUS_FIFOFULL) == 0 &&
                   priv->remaining > 0;
                   status = SDMMC.status.val)
                {
                  SDMMC.buffifo.val = *priv->buffer;
                  priv->buffer++;
                  priv->remaining -= 4;
                }
            }
          else if ((pending & SDMMC_LL_EVENT_RXDR) != 0)
            {
              uint32_t status;

              /* Transfer data from the RX FIFO */

              DEBUGASSERT(!priv->wrdir);

              for (status = SDMMC.status.val;
                   (status & SDMMC_STATUS_FIFOEMPTY) == 0 &&
                   priv->remaining > 0;
                   status = SDMMC.status.val)
                {
                  *priv->buffer = SDMMC.buffifo.val;
                  priv->buffer++;
                  priv->remaining -= 4;
                }
            }

          /* Check for transfer errors */

          /* Handle data block send/receive CRC failure */

          if ((pending & SDMMC_LL_EVENT_DCRC) != 0)
            {
              /* Terminate the transfer with an error */

              mcerr("ERROR: Data CRC failure, pending=%08" PRIx32
                    " remaining: %d\n", pending, priv->remaining);

              esp32p4_endtransfer(priv,
                                  SDIOWAIT_TRANSFERDONE | SDIOWAIT_ERROR);
            }

          /* Handle data timeout error */

          else if ((pending & SDMMC_LL_EVENT_RTO) != 0)
            {
              /* Terminate the transfer with an error */

              mcerr("ERROR: Data timeout, pending=%08" PRIx32
                    " remaining: %d\n", pending, priv->remaining);

              esp32p4_endtransfer(priv,
                                  SDIOWAIT_TRANSFERDONE | SDIOWAIT_TIMEOUT);
            }

          /* Handle RX FIFO overrun error */

          else if ((pending & SDMMC_LL_EVENT_FRUN) != 0)
            {
              /* Terminate the transfer with an error */

              mcerr("ERROR: RX FIFO overrun, pending=%08" PRIx32
                    " remaining: %d\n", pending, priv->remaining);

              esp32p4_endtransfer(priv,
                                  SDIOWAIT_TRANSFERDONE | SDIOWAIT_ERROR);
            }

          /* Handle start bit error */

          else if ((pending & SDMMC_LL_EVENT_SBE) != 0)
            {
              /* Terminate the transfer with an error */

              mcerr("ERROR: Start bit, pending=%08" PRIx32
                    " remaining: %d\n", pending, priv->remaining);

              esp32p4_endtransfer(priv,
                                  SDIOWAIT_TRANSFERDONE | SDIOWAIT_ERROR);
            }

          /* Handle data end events.  Note that RXDR may accompany DTO, DTO
           * will be set on received while there is still data in the FIFO.
           * So for the case of receiving, we don't actually even enable the
           * DTO interrupt.
           */

          else if ((pending & SDMMC_LL_EVENT_DTO) != 0)
            {
              /* Finish the transfer */

              esp32p4_endtransfer(priv, SDIOWAIT_TRANSFERDONE);
            }
        }

      /* Handle wait events *************************************************/

      pending = enabled & priv->waitmask;
      if (pending != 0)
        {
          /* Is this a response error event? */

          if ((pending & SDCARD_INT_RESPERR) != 0)
            {
              /* If response errors are enabled, then we must certainly be
               * waiting for a response.
               */

              DEBUGASSERT((priv->waitevents & SDIOWAIT_RESPONSEDONE) != 0);

              /* Wake the thread up */

              mcerr("ERROR: Response error, pending=%08" PRIx32 "\n", pending);
              esp32p4_endwait(priv, SDIOWAIT_RESPONSEDONE | SDIOWAIT_ERROR);
            }

          /* Is this a command (plus response) completion event? */

          else if ((pending & SDMMC_LL_EVENT_CMD_DONE) != 0)
            {
              /* Yes.. Is their a thread waiting for response done? */

              if ((priv->waitevents & SDIOWAIT_RESPONSEDONE) != 0)
                {
                  /* Yes.. wake the thread up */

                  esp32p4_endwait(priv, SDIOWAIT_RESPONSEDONE);
                }

              /* NO.. Is their a thread waiting for command done? */

              else if ((priv->waitevents & SDIOWAIT_CMDDONE) != 0)
                {
                  /* Yes.. wake the thread up */

                  esp32p4_endwait(priv, SDIOWAIT_CMDDONE);
                }
            }
        }
    }

#ifdef CONFIG_ESP32P4_SDMMC_DMA
  /* DMA error events *******************************************************/

  pending = sdmmc_ll_get_idsts_interrupt_raw(&SDMMC);
  if ((pending & priv->dmamask) != 0)
    {
      mcerr("ERROR: IDTS=%08" PRIx32 "\n", (uint32_t)pending);

      /* Clear the pending interrupts */

      sdmmc_ll_clear_idsts_interrupt(&SDMMC, pending);

      /* Abort the transfer */

      esp32p4_endtransfer(priv, SDIOWAIT_TRANSFERDONE | SDIOWAIT_ERROR);
    }
#endif

  return OK;
}

/****************************************************************************
 * Name: esp32p4_reset
 *
 * Description:
 *   Reset the SDIO controller.  Undo all setup and initialization.
 *
 * Input Parameters:
 *   dev    - An instance of the SDIO device interface
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_reset(struct sdio_dev_s *dev)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;
  irqstate_t flags;

  mcinfo("Resetting...\n");

  flags = enter_critical_section();

  /* Reset all blocks */

  sdmmc_ll_reset_controller(&SDMMC);
  sdmmc_ll_reset_dma(&SDMMC);
  sdmmc_ll_reset_fifo(&SDMMC);

  /* Wait for reset to complete */

  while (!sdmmc_ll_is_controller_reset_done(&SDMMC) ||
         !sdmmc_ll_is_dma_reset_done(&SDMMC) ||
         !sdmmc_ll_is_fifo_reset_done(&SDMMC))
    {
    }

  /* Initialize phase delays */

  sdmmc_ll_init_phase_delay(&SDMMC);

  /* Set card clock divider - slot selects clock divider */

  sdmmc_ll_set_card_clock_div(&SDMMC, priv->slot, priv->slot);

#ifdef CONFIG_ESP32P4_SDMMC_DMA
  sdmmc_ll_set_desc_addr(&SDMMC, (uint32_t)&priv->dma_desc[0]);
#endif

  /* Reset data */

  priv->waitevents = 0;      /* Set of events to be waited for */
  priv->waitmask   = 0;      /* Interrupt enables for event waiting */
  priv->wkupevent  = 0;      /* The event that caused the wakeup */

  wd_cancel(&priv->waitwdog); /* Cancel any timeouts */

  /* Interrupt mode data transfer support */

  priv->buffer     = 0;      /* Address of current R/W buffer */
  priv->remaining  = 0;      /* Number of bytes remaining in the transfer */
  priv->xfrmask    = 0;      /* Interrupt enables for data transfer */
#ifdef CONFIG_ESP32P4_SDMMC_DMA
  priv->dmamask    = 0;      /* Interrupt enables for DMA transfer */
#endif

  /* DMA data transfer support */

  priv->cdstatus   = 0;      /* Card status is unknown */

  leave_critical_section(flags);
}

/****************************************************************************
 * Name: esp32p4_capabilities
 *
 * Description:
 *   Get capabilities (and limitations) of the SDIO driver (optional)
 *
 * Input Parameters:
 *   dev   - Device-specific state data
 *
 * Returned Value:
 *   Returns a bitset of status values (see SDIO_CAPS_* defines)
 *
 ****************************************************************************/

static sdio_capset_t esp32p4_capabilities(struct sdio_dev_s *dev)
{
  sdio_capset_t caps = 0;

  caps |= SDIO_CAPS_DMABEFOREWRITE;
  caps |= SDIO_CAPS_MMC_HS_MODE;

#ifdef CONFIG_SDIO_WIDTH_D1_ONLY
  caps |= SDIO_CAPS_1BIT_ONLY;
#else
  caps |= SDIO_CAPS_4BIT;
#endif
#ifdef CONFIG_ESP32P4_SDMMC_DMA
  caps |= SDIO_CAPS_DMASUPPORTED;
#endif

  return caps;
}

/****************************************************************************
 * Name: esp32p4_status
 *
 * Description:
 *   Get SDIO status.
 *
 * Input Parameters:
 *   dev   - Device-specific state data
 *
 * Returned Value:
 *   Returns a bitset of status values (see esp32p4_status_* defines)
 *
 ****************************************************************************/

static sdio_statset_t esp32p4_status(struct sdio_dev_s *dev)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;

#ifdef CONFIG_MMCSD_HAVE_CARDDETECT
  if (!sdmmc_ll_is_card_detected(&SDMMC, priv->slot))
    {
      priv->cdstatus |= SDIO_STATUS_PRESENT;
    }
  else
    {
      priv->cdstatus &= ~SDIO_STATUS_PRESENT;
    }
#endif

  mcinfo("cdstatus=%02x\n", priv->cdstatus);

  return priv->cdstatus;
}

/****************************************************************************
 * Name: esp32p4_widebus
 *
 * Description:
 *   Called after change in Bus width has been selected (via ACMD6).  Most
 *   controllers will need to perform some special operations to work
 *   correctly in the new bus mode.
 *
 * Input Parameters:
 *   dev  - An instance of the SDIO device interface
 *   wide - true: wide bus (4-bit) bus mode enabled
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_widebus(struct sdio_dev_s *dev, bool wide)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;

  if (wide)
    {
      sdmmc_ll_set_card_width(&SDMMC, priv->slot, SD_BUS_WIDTH_4_BIT);
    }
  else
    {
      sdmmc_ll_set_card_width(&SDMMC, priv->slot, SD_BUS_WIDTH_1_BIT);
    }

  mcinfo("slot=%d wide=%d\n", priv->slot, wide ? 1 : 0);
}

