input.new_string:
/****************************************************************************
 * Name: sdmmc_host_clock_update_command
 *
 * Description:
 *   Send a clock update command to CIU. This is not a real command;
 *   it just updates CIU registers (CLKDIV, CLKSRC, CLKENA).
 *
 * Input Parameters:
 *   priv - A reference to the SD card device state structure
 *
 * Returned Value:
 *   OK on success; a negated errno on failure
 *
 ****************************************************************************/

static int sdmmc_host_clock_update_command(struct esp32p4_dev_s *priv)
{
  sdmmc_hw_cmd_t cmd_val;
  clock_t watchtime;

  memset(&cmd_val, 0, sizeof(cmd_val));
  cmd_val.update_clk_reg = 1;
  cmd_val.wait_complete = 1;
  cmd_val.card_num = priv->slot;
  cmd_val.use_hold_reg = 1;
  cmd_val.start_command = 1;

  /* Wait for previous command to be taken */

  watchtime = clock_systime_ticks();
  while (!sdmmc_ll_is_command_taken(&SDMMC))
    {
      if (clock_systime_ticks() - watchtime > SDCARD_CMDTIMEOUT)
        {
          mcerr("TMO waiting for command taken\n");
          return -ETIMEDOUT;
        }
    }

  sdmmc_ll_set_command_arg(&SDMMC, 0);
  sdmmc_ll_set_command(&SDMMC, cmd_val);

  /* Wait for command to complete */

  watchtime = clock_systime_ticks();
  while (!sdmmc_ll_is_command_taken(&SDMMC))
    {
      if (clock_systime_ticks() - watchtime > SDCARD_CMDTIMEOUT)
        {
          mcerr("TMO waiting for clock update complete\n");
          return -ETIMEDOUT;
        }
    }

  return OK;
}

/****************************************************************************
 * Name: sdmmc_host_get_clk_dividers
 *
 * Description:
 *   Calculate clock dividers for the requested frequency.
 *
 *   We have two clock divider stages:
 *   - Host divider: divides the source clock (160MHz PLL160M)
 *   - Card divider: divides the host clock by 2*n
 *
 * Input Parameters:
 *   freq_khz - Requested frequency in kHz
 *   host_div - Output: host clock divider
 *   card_div - Output: card clock divider
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void sdmmc_host_get_clk_dividers(uint32_t freq_khz, int *host_div,
                                        int *card_div)
{
  /* For ESP32P4, we use PLL160M (160MHz) as the source clock.
   *
   * The host divider can be 1-16 (configured in HP_SYS_CLKRST registers).
   * The card divider can be 0 (bypass) or 1-255 (actual div = 2*card_div).
   *
   * actual_freq = clk_src / host_div                   when card_div == 0
   * actual_freq = clk_src / host_div / (2 * card_div)  when card_div > 0
   */

  uint32_t clk_src_freq_khz = BOARD_SDMMC_FREQUENCY / 1000;

  if (freq_khz >= clk_src_freq_khz)
    {
      /* Maximum frequency: source clock / 1 */

      *host_div = 1;
      *card_div = 0;
    }
  else if (freq_khz >= clk_src_freq_khz / 2)
    {
      *host_div = 2;
      *card_div = 0;
    }
  else if (freq_khz >= clk_src_freq_khz / 4)
    {
      *host_div = 4;
      *card_div = 0;
    }
  else if (freq_khz >= clk_src_freq_khz / 8)
    {
      *host_div = 8;
      *card_div = 0;
    }
  else if (freq_khz >= clk_src_freq_khz / 16)
    {
      *host_div = 16;
      *card_div = 0;
    }
  else
    {
      /* Need two-stage division */

      uint32_t target_hz = freq_khz * 1000;
      uint32_t total_div = (BOARD_SDMMC_FREQUENCY + target_hz - 1) / target_hz;

      if (total_div <= 16)
        {
          *host_div = (int)total_div;
          *card_div = 0;
        }
      else
        {
          /* Two-stage: find best combination */

          *host_div = 2;
          *card_div = 255;
          for (int h = 2; h <= 16; h++)
            {
              uint32_t intermediate = BOARD_SDMMC_FREQUENCY / h;
              int c = (int)((intermediate + 2 * target_hz - 1) /
                       (2 * target_hz));
              if (c < 1)
                {
                  c = 1;
                }
              if (c <= 255)
                {
                  *host_div = h;
                  *card_div = c;
                  break;
                }
            }
        }
    }

  mcinfo("freq_khz=%" PRIu32 " host_div=%d card_div=%d\n",
         freq_khz, *host_div, *card_div);
}

/****************************************************************************
 * Name: sdmmc_host_set_clk_div
 *
 * Description:
 *   Set the clock dividers in the hardware.
 *
 * Input Parameters:
 *   slot     - Slot number
 *   host_div - Host clock divider
 *   card_div - Card clock divider
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void sdmmc_host_set_clk_div(uint32_t slot, uint32_t host_div,
                                   uint32_t card_div)
{
  /* Disable card clock first */

  sdmmc_ll_enable_card_clock(&SDMMC, slot, false);
  sdmmc_host_clock_update_command(&g_sdiodev);

  /* Set host clock divider (in HP_SYS_CLKRST registers) */

  sdmmc_ll_set_clock_div(&SDMMC, host_div);

  /* Select PLL160M as clock source */

  sdmmc_ll_select_clk_source(&SDMMC, SDMMC_CLK_SRC_PLL160M);

  /* Initialize phase delays */

  sdmmc_ll_init_phase_delay(&SDMMC);

  /* Set card clock divider */

  sdmmc_ll_set_card_clock_div(&SDMMC, slot, card_div);

  /* Send clock update command */

  sdmmc_host_clock_update_command(&g_sdiodev);

  /* Re-enable card clock */

  sdmmc_ll_enable_card_clock(&SDMMC, slot, true);
  sdmmc_ll_enable_card_clock_low_power(&SDMMC, slot, true);
  sdmmc_host_clock_update_command(&g_sdiodev);

  /* Set timeouts */

  uint32_t freq_khz = BOARD_SDMMC_FREQUENCY / host_div /
                       ((card_div == 0) ? 1 : card_div * 2) / 1000;
  uint32_t data_timeout_ms = 100;
  uint32_t data_timeout_cycles = data_timeout_ms * freq_khz;
  sdmmc_ll_set_data_timeout(&SDMMC, data_timeout_cycles);
  sdmmc_ll_set_response_timeout(&SDMMC, 255);

  mcinfo("slot=%" PRIu32 " host_div=%" PRIu32 " card_div=%" PRIu32 "\n",
         slot, host_div, card_div);
}

/****************************************************************************
 * Name: esp32p4_clock
 *
 * Description:
 *   Enable/disable SDIO clocking
 *
 * Input Parameters:
 *   dev  - An instance of the SDIO device interface
 *   rate - Specifies the clocking to use (see enum sdio_clock_e)
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_clock(struct sdio_dev_s *dev, enum sdio_clock_e rate)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;
  uint32_t freq_khz;
  int host_div;
  int card_div;

  mcinfo("rate=%d\n", rate);

  switch (rate)
    {
      case CLOCK_SDIO_DISABLED:
        sdmmc_ll_enable_card_clock(&SDMMC, priv->slot, false);
        sdmmc_host_clock_update_command(priv);
        return;

      case CLOCK_IDMODE:
        /* Initial ID mode clocking (<400KHz) */

        freq_khz = 400;
        break;

      case CLOCK_MMC_TRANSFER:
        /* MMC normal operation clocking (up to 52MHz) */

        freq_khz = 52000;
        break;

      case CLOCK_SD_TRANSFER_1BIT:
      case CLOCK_SD_TRANSFER_4BIT:
        /* SD normal operation clocking (up to 50MHz) */

        freq_khz = 50000;
        break;

      default:
        mcerr("ERROR: Unknown rate: %d\n", rate);
        return;
    }

  /* Calculate and set clock dividers */

  sdmmc_host_get_clk_dividers(freq_khz, &host_div, &card_div);
  sdmmc_host_set_clk_div(priv->slot, host_div, card_div);
}

/****************************************************************************
 * Name: esp32p4_attach
 *
 * Description:
 *   Attach and prepare interrupts
 *
 * Input Parameters:
 *   dev - An instance of the SDIO device interface
 *
 * Returned Value:
 *   OK on success; A negated errno on failure.
 *
 ****************************************************************************/

static int esp32p4_attach(struct sdio_dev_s *dev)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;
  int ret;

  /* Attach the SDMMC interrupt handler */

  ret = irq_attach(ESP32P4_IRQ_SDIO_HOST, esp32p4_interrupt, priv);
  if (ret < 0)
    {
      mcerr("ERROR: Failed to attach IRQ: %d\n", ret);
      return ret;
    }

  /* Enable the interrupt at the NVIC */

  up_enable_irq(ESP32P4_IRQ_SDIO_HOST);

  /* Enable global SDMMC interrupt */

  sdmmc_ll_enable_global_interrupt(&SDMMC, true);

  mcinfo("Attached IRQ\n");

  return OK;
}

/****************************************************************************
 * Name: esp32p4_sendcmd
 *
 * Description:
 *   Send the SDIO command
 *
 * Input Parameters:
 *   dev  - An instance of the SDIO device interface
 *   cmd  - The command to send (32-bits, encoded)
 *   arg  - 32-bit argument required with some commands
 *
 * Returned Value:
 *   OK on success; a negated errno on failure
 *
 ****************************************************************************/

static int esp32p4_sendcmd(struct sdio_dev_s *dev, uint32_t cmd, uint32_t arg)
{
  mcinfo("cmd: %08" PRIx32 " arg: %08" PRIx32 "\n", cmd, arg);

  /* Send the command via CIU */

  if (esp32p4_ciu_sendcmd(cmd, arg) != 0)
    {
      mcerr("ERROR: Failed to send command\n");
      return -ETIMEDOUT;
    }

  return OK;
}

/****************************************************************************
 * Name: esp32p4_recvsetup
 *
 * Description:
 *   Setup hardware in preparation for data transfer from the card in non-DMA
 *   (interrupt driven mode).  This method will do whatever controller setup
 *   is necessary.  This would be called for SD memory just BEFORE sending
 *   CMD13 (SEND_STATUS), CMD17 (READ_SINGLE_BLOCK), CMD18
 *   (READ_MULTIPLE_BLOCKS), ACMD51 (SEND_SCR), etc.  Normally,
 *   SDIO_WAITEVENT will be called to receive the indication that the
 *   transfer is complete.
 *
 * Input Parameters:
 *   dev    - An instance of the SDIO device interface
 *   buffer - Address of the buffer in which to receive the data
 *   nbytes - The number of bytes in the transfer
 *
 * Returned Value:
 *   Number of bytes sent on success; a negated errno on failure
 *
 ****************************************************************************/

static int esp32p4_recvsetup(struct sdio_dev_s *dev, uint8_t *buffer,
                             size_t nbytes)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;

  mcinfo("buffer=%p nbytes=%zu\n", buffer, nbytes);

  /* Reset the FIFO */

  sdmmc_ll_reset_fifo(&SDMMC);
  while (!sdmmc_ll_is_fifo_reset_done(&SDMMC))
    {
    }

  /* Set up the data transfer */

  priv->buffer    = (uint32_t *)buffer;
  priv->remaining = nbytes;
  priv->wrdir     = false;

  /* Set byte count */

  sdmmc_ll_set_data_transfer_len(&SDMMC, nbytes);

  /* Enable receive interrupts */

  esp32p4_config_xfrints(priv, SDCARD_DMARECV_MASK);

  return OK;
}

/****************************************************************************
 * Name: esp32p4_sendsetup
 *
 * Description:
 *   Setup hardware in preparation for data transfer from the card.  This
 *   method will do whatever controller setup is necessary.  This would be
 *   called for SD memory just AFTER sending CMD24 (WRITE_BLOCK), CMD25
 *   (WRITE_MULTIPLE_BLOCK), ... and before SDIO_SENDDATA is called.
 *
 * Input Parameters:
 *   dev    - An instance of the SDIO device interface
 *   buffer - Address of the buffer containing the data to send
 *   nbytes - The number of bytes in the transfer
 *
 * Returned Value:
 *   Number of bytes sent on success; a negated errno on failure
 *
 ****************************************************************************/

static int esp32p4_sendsetup(struct sdio_dev_s *dev, const uint8_t *buffer,
                             size_t nbytes)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;

  mcinfo("buffer=%p nbytes=%zu\n", buffer, nbytes);

  /* Reset the FIFO */

  sdmmc_ll_reset_fifo(&SDMMC);
  while (!sdmmc_ll_is_fifo_reset_done(&SDMMC))
    {
    }

  /* Set up the data transfer */

  priv->buffer    = (uint32_t *)buffer;
  priv->remaining = nbytes;
  priv->wrdir     = true;

  /* Set byte count */

  sdmmc_ll_set_data_transfer_len(&SDMMC, nbytes);

  /* Enable transmit interrupts */

  esp32p4_config_xfrints(priv, SDCARD_DMASEND_MASK);

  return OK;
}

/****************************************************************************
 * Name: esp32p4_cancel
 *
 * Description:
 *   Cancel the data transfer setup of SDIO_RECVSETUP, SDIO_SENDSETUP,
 *   SDIO_DMARECVSETUP or SDIO_DMASENDSETUP.  This must be called to cancel
 *   the data transfer setup if, for some reason, you cannot perform the
 *   transfer.
 *
 * Input Parameters:
 *   dev  - An instance of the SDIO device interface
 *
 * Returned Value:
 *   OK is success; a negated errno on failure
 *
 ****************************************************************************/

static int esp32p4_cancel(struct sdio_dev_s *dev)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;

  mcinfo("Cancelling transfer\n");

  /* Disable all transfer-related interrupts */

  esp32p4_disable_allints(priv);

  /* Reset the data state machine */

  SDMMC.ctrl.abort_read_data = 1;

  /* Wait for the abort to complete */

  clock_t watchtime = clock_systime_ticks();
  while (SDMMC.ctrl.abort_read_data)
    {
      if (clock_systime_ticks() - watchtime > SDCARD_CMDTIMEOUT)
        {
          mcerr("TMO waiting for abort\n");
          break;
        }
    }

  /* Reset the FIFO */

  sdmmc_ll_reset_fifo(&SDMMC);
  while (!sdmmc_ll_is_fifo_reset_done(&SDMMC))
    {
    }

  /* Clear any pending interrupts */

  sdmmc_ll_clear_interrupt(&SDMMC, 0xffffffff);

#ifdef CONFIG_ESP32P4_SDMMC_DMA
  /* Stop DMA */

  sdmmc_ll_stop_dma(&SDMMC);
  sdmmc_ll_clear_idsts_interrupt(&SDMMC, 0xffffffff);
#endif

  priv->remaining = 0;
  priv->buffer    = NULL;

  return OK;
}

/****************************************************************************
 * Name: esp32p4_waitresponse
 *
 * Description:
 *   Poll-wait for the response to the last command to be ready.  This
 *   function should be called even after sending commands that have no
 *   response (such as CMD0) to make sure that the hardware is ready to
 *   receive the next command.
 *
 * Input Parameters:
 *   dev  - An instance of the SDIO device interface
 *   cmd  - The command that was sent. See 32-bit command definitions above.
 *
 * Returned Value:
 *   OK is success; a negated errno on failure
 *
 ****************************************************************************/

static int esp32p4_waitresponse(struct sdio_dev_s *dev, uint32_t cmd)
{
  clock_t watchtime;
  uint32_t status;

  mcinfo("cmd: %08" PRIx32 "\n", cmd);

  /* Wait for command completion or response.
   *
   * Poll-wait for the command to complete.  This is not the normal path
   * for SDIO operations; normally, the interrupt handler will detect
   * command completion.
   */

  watchtime = clock_systime_ticks();

  for (; ; )
    {
      /* Check for command done */

      status = sdmmc_ll_get_interrupt_raw(&SDMMC);

      if ((status & SDMMC_LL_EVENT_CMD_DONE) != 0)
        {
          /* Clear the command done interrupt */

          sdmmc_ll_clear_interrupt(&SDMMC, SDMMC_LL_EVENT_CMD_DONE);
          break;
        }

      /* Check for response timeout */

      if ((status & SDMMC_LL_EVENT_RTO) != 0)
        {
          /* Clear the timeout interrupt */

          sdmmc_ll_clear_interrupt(&SDMMC, SDMMC_LL_EVENT_RTO);
          mcerr("ERROR: Response timeout\n");
          return -ETIMEDOUT;
        }

      /* Check for response CRC error */

      if ((status & SDMMC_LL_EVENT_RCRC) != 0)
        {
          /* Clear the CRC error interrupt */

          sdmmc_ll_clear_interrupt(&SDMMC, SDMMC_LL_EVENT_RCRC);
          mcerr("ERROR: Response CRC error\n");
          return -EIO;
        }

      /* Check for response error */

      if ((status & SDMMC_LL_EVENT_RESP_ERR) != 0)
        {
          /* Clear the response error interrupt */

          sdmmc_ll_clear_interrupt(&SDMMC, SDMMC_LL_EVENT_RESP_ERR);
          mcerr("ERROR: Response error\n");
          return -EIO;
        }

      /* Check for timeout */

      if ((clock_systime_ticks() - watchtime) > SDCARD_CMDTIMEOUT)
        {
          mcerr("TMO waiting for response\n");
          return -ETIMEDOUT;
        }
    }

  return OK;
}

/****************************************************************************
 * Name: esp32p4_waitenable
 *
 * Description:
 *   Enable/disable of a set of SDIO wait events.  This is part of the
 *   the SDIO_WAITEVENT sequence.  The set of to-be-waited-for events is
 *   configured before calling esp32p4_eventwait.  This is done in this way
 *   to help the driver to eliminate race conditions between the command
 *   setup and the subsequent events.
 *
 *   The enabled events persist until either (1) SDIO_WAITENABLE is called
 *   again specifying a different set of wait events, or (2) SDIO_EVENTWAIT
 *   returns.
 *
 * Input Parameters:
 *   dev      - An instance of the SDIO device interface
 *   eventset - A bitset of events to enable or disable (see SDIOWAIT_*
 *              definitions). 0=disable; 1=enable.
 *   timeout  - Maximum time in milliseconds to wait
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void esp32p4_waitenable(struct sdio_dev_s *dev, sdio_eventset_t eventset,
                               uint32_t timeout)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;
  uint32_t waitmask = 0;

  mcinfo("eventset: %02x timeout: %" PRIu32 "\n", eventset, timeout);

  /* Disable previous wait interrupts */

  esp32p4_config_waitints(priv, 0, 0, 0);

  /* Clear any pending interrupts */

  sdmmc_ll_clear_interrupt(&SDMMC, 0xffffffff);

  /* Enable interrupts based on the requested events */

  if ((eventset & SDIOWAIT_CMDDONE) != 0)
    {
      waitmask |= SDCARD_CMDDONE_MASK;
    }

  if ((eventset & SDIOWAIT_RESPONSEDONE) != 0)
    {
      waitmask |= SDCARD_RESPDONE_MASK;
    }

  if ((eventset & SDIOWAIT_TIMEOUT) != 0)
    {
      /* Start the watchdog timer */

      wd_start(&priv->waitwdog, MSEC2TICK(timeout),
               esp32p4_eventtimeout, (wdparm_t)priv);
    }

  /* Enable the wait interrupts */

  esp32p4_config_waitints(priv, waitmask, eventset, 0);
}

/****************************************************************************
 * Name: esp32p4_eventwait
 *
 * Description:
 *   Wait for one of the enabled events to occur (or a timeout).  Note that
 *   all events enabled by SDIO_WAITEVENTS are disabled when
 *   esp32p4_eventwait returns.  SDIO_WAITEVENTS must be called again before
 *   esp32p4_eventwait can be used again.
 *
 * Input Parameters:
 *   dev - An instance of the SDIO device interface
 *
 * Returned Value:
 *   Event set containing the event(s) that ended the wait.  Should always
 *   be non-zero.  All events are disabled after the wait concludes.
 *
 ****************************************************************************/

static sdio_eventset_t esp32p4_eventwait(struct sdio_dev_s *dev)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;
  sdio_eventset_t wkupevent;
  irqstate_t flags;
  int ret;

  mcinfo("Waiting for events\n");

  /* Wait for the posted semaphore event */

  ret = nxsem_wait(&priv->waitsem);
  if (ret < 0)
    {
      mcerr("ERROR: nxsem_wait failed: %d\n", ret);
      return SDIOWAIT_ERROR;
    }

  /* Return the event that caused the wakeup */

  flags = enter_critical_section();
  wkupevent = priv->wkupevent;
  priv->wkupevent = 0;
  leave_critical_section(flags);

  mcinfo("wkupevent=%02x\n", wkupevent);

  return wkupevent;
}

/****************************************************************************
 * Name: esp32p4_registercallback
 *
 * Description:
 *   Register a callback that that will be invoked on any media status
 *   change.  Callbacks should not be made from interrupt handlers, rather
 *   interrupt level events should be handled by calling back on the work
 *   thread.
 *
 *   When this method is called, all callbacks should be disabled until they
 *   are enabled via a call to SDIO_CALLBACKENABLE
 *
 * Input Parameters:
 *   dev -      Device-specific state data
 *   callback - The function to call on the media change
 *   arg -      A caller provided value to return with the callback
 *
 * Returned Value:
 *   0 on success; negated errno on failure.
 *
 ****************************************************************************/

static int esp32p4_registercallback(struct sdio_dev_s *dev, worker_t callback,
                                    void *arg)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)dev;
  irqstate_t flags;

  mcinfo("Registering callback\n");

  /* Disable callbacks while changing the handler */

  flags = enter_critical_section();
  priv->callback = callback;
  priv->cbarg    = arg;
  leave_critical_section(flags);

  return OK;
}

/****************************************************************************
 * Name: esp32p4_callback
 *
 * Description:
 *   Perform callback.
 *
 * Assumptions:
 *   This function does not execute in the context of an interrupt handler.
 *   It may be invoked on any user thread or scheduled on the work thread
 *   from an interrupt handler.
 *
 ****************************************************************************/

static void esp32p4_callback(void *arg)
{
  struct esp32p4_dev_s *priv = (struct esp32p4_dev_s *)arg;

  mcinfo("Performing callback\n");

  /* Is a callback registered? */

  if (priv->callback)
    {
      /* Yes.. perform the callback */

      priv->callback(&priv->dev, priv->cbarg);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sdio_initialize
 *
 * Description:
 *   Initialize SDIO for operation.
 *
 * Input Parameters:
 *   slotno - SDMMC slot number (0 for IOMUX TF card, 1 for GPIO-matrix
 *            ESP-Hosted SDIO to ESP32-C6)
 *
 * Returned Value:
 *   A reference to an SDIO interface structure.  NULL is returned on
 *   failures.
 *
 ****************************************************************************/

struct sdio_dev_s *sdio_initialize(int slotno)
{
  struct esp32p4_dev_s *priv = &g_sdiodev;

  mcinfo("slotno=%d\n", slotno);

  /* Check if already initialized */

  if (priv->inited)
    {
      mcinfo("Already initialized\n");
      return &priv->dev;
    }

  /* Set the slot number */

  priv->slot = slotno;

  /* Enable SDMMC bus clock */

  sdmmc_ll_enable_bus_clock(0, true);
  sdmmc_ll_reset_register(0);

  /* Initialize DMA */

#ifdef CONFIG_ESP32P4_SDMMC_DMA
  sdmmc_ll_init_dma(&SDMMC);
#endif

  /* Perform initial reset */

  esp32p4_reset(&priv->dev);

  /* Set initial clock to 400kHz for identification mode */

  esp32p4_clock(&priv->dev, CLOCK_IDMODE);

  /* Mark as initialized */

  priv->inited = true;

  mcinfo("SDIO initialized for slot %d\n", slotno);

  return &priv->dev;
}

