/****************************************************************************
 * Name: esp32p4_dmarecvsetup
 *
 * Description:
 *   Setup to perform a DMA read. This is an alternative to esp32p4_recvsetup.
 *   NOTE: The DMA descriptors must be set up before calling this function.
 *
 * Input Parameters:
 *   dev    - An instance of the SDIO device interface
 *   buffer - Address of the buffer in which to receive the data
 *   buflen - The number of bytes in the transfer
 *
 * Returned Value:
 *   OK on success; a negated errno on failure
 *
 ****************************************************************************/

#ifdef CONFIG_ESP32P4_SDMMC_DMA
static int esp32p4_dmarecvsetup(struct sdio_dev_s* dev, uint8_t* buffer,
                                size_t buflen)
{
  struct esp32p4_dev_s* priv = (struct esp32p4_dev_s*)dev;

  mcinfo("buffer=%p buflen=%zu\n", buffer, buflen);

  DEBUGASSERT(buffer != NULL && buflen > 0);

  /* Set up the data transfer */

  priv->buffer    = (uint32_t*)buffer;
  priv->remaining = buflen;
  priv->wrdir     = false;

  /* Set byte count */

  sdmmc_ll_set_data_transfer_len(&SDMMC, buflen);

  /* Enable DMA receive interrupts */

  esp32p4_config_xfrints(priv, SDCARD_DMARECV_MASK);

  return OK;
}
#endif

/****************************************************************************
 * Name: esp32p4_dmasendsetup
 *
 * Description:
 *   Setup to perform a DMA write. This is an alternative to
 *   esp32p4_sendsetup.  NOTE: The DMA descriptors must be set up before
 *   calling this function.
 *
 * Input Parameters:
 *   dev    - An instance of the SDIO device interface
 *   buffer - Address of the buffer containing the data to send
 *   buflen - The number of bytes in the transfer
 *
 * Returned Value:
 *   OK on success; a negated errno on failure
 *
 ****************************************************************************/

#ifdef CONFIG_ESP32P4_SDMMC_DMA
static int esp32p4_dmasendsetup(struct sdio_dev_s* dev,
                                const uint8_t* buffer, size_t buflen)
{
  struct esp32p4_dev_s* priv = (struct esp32p4_dev_s*)dev;

  mcinfo("buffer=%p buflen=%zu\n", buffer, buflen);

  DEBUGASSERT(buffer != NULL && buflen > 0);

  /* Set up the data transfer */

  priv->buffer    = (uint32_t*)buffer;
  priv->remaining = buflen;
  priv->wrdir     = true;

  /* Set byte count */

  sdmmc_ll_set_data_transfer_len(&SDMMC, buflen);

  /* Enable DMA send interrupts */

  esp32p4_config_xfrints(priv, SDCARD_DMASEND_MASK);

  return OK;
}
#endif

/****************************************************************************
 * Name: esp32p4_readfifo
 *
 * Description:
 *   Read remaining data from the FIFO after a transfer completes.
 *   This is used to drain any data left in the FIFO after the DMA
 *   transfer is done.
 *
 * Input Parameters:
 *   dev    - An instance of the SDIO device interface
 *   buffer - Address of the buffer in which to receive the data
 *
 * Returned Value:
 *   OK on success; a negated errno on failure
 *
 ****************************************************************************/

static int esp32p4_readfifo(struct sdio_dev_s* dev, uint32_t* buffer)
{
  struct esp32p4_dev_s* priv = (struct esp32p4_dev_s*)dev;

  mcinfo("buffer=%p\n", buffer);

  DEBUGASSERT(buffer != NULL);

  /* Read data from the FIFO until empty */

  while (!SDMMC.status.fifo_empty && priv->remaining > 0)
    {
      *buffer = SDMMC.buffifo.val;
      buffer++;
      priv->remaining -= 4;
    }

  return OK;
}

